fn receive(program: &ResolvedProgram, function: &ResolvedFunction, facts: &Facts<'_>,
    storage: &BTreeSet<StorageId>, leaves: &Leaves, budget: &mut ReplayBudget,
    current: bool) -> Result<(), Diagnostic>
{
