}

// Independently price the actual removed lookups on the same immutable arena.
// Bootstrap the unchanged old receiver first; no fixture-gap numeric is fitted.
fn removed_lookup_cost(function: &ResolvedFunction) -> (usize, usize) {
    let mut preparation = ReplayBudget::unobserved();
    let facts = Facts::Arena(super::super::super::arena::build::<errors::Legacy>(function,
        capacity::Payer::Selected(&mut physical_storage::PhysicalReservation::new(usize::MAX)),
        &mut preparation).unwrap());
    let ((cost, allocation), refused, _, _) = with_limit_usage_refusal(1 << 26, || measure(|| {
        let mut budget = ReplayBudget::new();
        drop(status_before::validate_status_sources_retained(function, &facts, &mut budget).unwrap());
        let work = budget.remaining;
        let bytes = crate::bounded_output::active_remaining().unwrap();
        for source in &function.cleanup_plan.status_sources {
            if let StatusProducer::PropagatedCall { callee } = &source.producer {
                let Some(Some(call)) = facts.fact(function, &source.id.expression, &mut budget).unwrap()
                    else { panic!("complete old receiver authenticated this exact call"); };
                assert_eq!(call.callee.as_ref(), callee);
            }
        }
        let cost = (work - budget.remaining,
            bytes - crate::bounded_output::active_remaining().unwrap());
        drop(budget);
        cost
    }));
    assert!(!refused && !allocation.invalid);
    assert_eq!(allocation.live, 0); assert_eq!(allocation.allocated, allocation.freed);
    cost
}

#[test]
fn complete_status_receivers_preserve_call_payload_six_fields_priority_and_drop() {
    let program = program();
    let mut saved = false;
    let mut attacked_call = false;
    for function in &program.functions {
        let expected = original(&program, function);
        assert!(expected.is_ok());
        let old = observe(&program, function, false, MAX_REPLAY_WORK_UNITS, 1 << 26, Some(&expected));
        let new = observe(&program, function, true, MAX_REPLAY_WORK_UNITS, 1 << 26, Some(&expected));
        assert!(old.0 && new.0 && !old.3 && !new.3);
        // Keep the complete earlier component's exact equations independent.
        // The actual production receiver above still runs with every original
        // hostile/physical/Drop control; prefix work is a separate algorithm.
        let component = component_before_prefix::observe(&program, function, true,
            MAX_REPLAY_WORK_UNITS, 1 << 26, Some(&expected));
        assert!(component.0 && !component.3);
        assert!(old.5 <= old.2 && new.5 <= new.2 && component.5 <= component.2);
        {
        let new = component;
        let calls = function.cleanup_plan.status_sources.iter()
            .filter(|source| matches!(source.producer, StatusProducer::PropagatedCall { .. })).count();
        let receiving_bytes = function.cleanup_plan.status_sources.len()
            .checked_mul(std::mem::size_of::<&Option<CallFact<'_>>>()).unwrap()
            .checked_add(calls.checked_mul(std::mem::size_of::<&CallFact<'_>>()).unwrap()).unwrap();
        let assignments = function.cleanup_plan.status_sources.len().checked_add(calls).unwrap();
        let removed = removed_lookup_cost(function);
        assert_eq!(old.1.checked_add(assignments).unwrap(), new.1.checked_add(removed.0).unwrap());
        assert_eq!(old.2.checked_add(receiving_bytes).unwrap(), new.2.checked_add(removed.1).unwrap());
        if function.cleanup_plan.status_sources.iter().any(|s| matches!(s.producer, StatusProducer::PropagatedCall { .. })) {
            assert!(new.1 < old.1 && new.2 < old.2);
            assert!(new.5 <= old.5); // Receiving control is fully paid and allocation-free.
            saved = true;
        }
        }
        let mut attacks = Vec::new();
        if let Some(source) = function.cleanup_plan.status_sources.first() {
            let mut bad = function.clone(); bad.cleanup_plan.status_sources.push(source.clone()); attacks.push(bad);
            let mut bad = function.clone(); bad.cleanup_plan.status_sources[0].id.expression =
                ExpressionId::from_owned("foreign.first.status".into()); attacks.push(bad);
            // Unknown current source wins before a later duplicate/callee failure.
            let mut bad = function.clone(); bad.cleanup_plan.status_sources[0].id.expression =
                ExpressionId::from_owned("foreign.first.status".into());
            bad.cleanup_plan.status_sources.push(source.clone()); attacks.push(bad);
        }
        for (at, source) in function.cleanup_plan.status_sources.iter().enumerate() {
            if let StatusProducer::PropagatedCall { .. } = &source.producer {
                attacked_call = true;
                let wrong = program.functions.iter().find(|other| {
                    match &source.producer { StatusProducer::PropagatedCall { callee } => other.id != *callee, _ => false }
                }).unwrap().id.clone();
                let mut bad = function.clone();
                bad.cleanup_plan.status_sources[at].producer = StatusProducer::PropagatedCall { callee: wrong.clone() };
                attacks.push(bad);
                // Duplicate insertion wins over the duplicate's malformed callee.
                let mut bad = function.clone(); let mut duplicate = source.clone();
                duplicate.producer = StatusProducer::PropagatedCall { callee: wrong.clone() };
                bad.cleanup_plan.status_sources.push(duplicate); attacks.push(bad);
                // Existing non-call expression is distinct from unknown expression.
                let mut bad = function.clone(); bad.cleanup_plan.status_sources[at].id.expression = function.body.id.clone();
                attacks.push(bad);
                let mut bad = function.clone(); bad.cleanup_plan.status_sources[at].id.lane = StatusLane::ContractFalse;
                attacks.push(bad);
                break;
            }
        }
        for hostile in attacks {
            let expected = original(&program, &hostile);
            assert!(expected.is_err());
            for current in [false, true] {
                let result = observe(&program, &hostile, current, MAX_REPLAY_WORK_UNITS, 1 << 26, Some(&expected));
                assert!(!result.0 && !result.3);
            }
        }
    }
    assert!(saved && attacked_call);
}

#[test]
fn actual_status_borrow_receivers_keep_own_exact_short_zero_work_and_bytes() {
    let program = program();
    let function = program.functions.iter().find(|f| f.cleanup_plan.status_sources.iter()
        .any(|s| matches!(s.producer, StatusProducer::PropagatedCall { .. }))).unwrap();
    for current in [false, true] {
        let full = observe(&program, function, current, MAX_REPLAY_WORK_UNITS, 1 << 26, None);
        assert!(full.0 && !full.3 && full.1 > 0 && full.2 > 0);
        for limit in [0, full.1-1, full.1] {
            let result = observe(&program, function, current, limit, 1 << 26, None);
            assert_eq!(result.0, limit == full.1); assert!(!result.3);
            if result.0 { assert_eq!(result.1, full.1); }
        }
