            include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/docs/evidence/status-fact-borrow-reuse/retained_tests.rs.before.txt"))),
    ];
    for row in rows.as_array().unwrap() {
        let fixed_hash = fixed.iter().find(|(path, _)| *path == row["source"].as_str().unwrap()).unwrap().1;
        assert_eq!(row["sha256"].as_str().unwrap(), fixed_hash);
        let (_, current, archive) = sources.iter()
            .find(|(path, _, _)| *path == row["source"].as_str().unwrap()).unwrap();
        let mut source = (*current).to_owned();
        assert_eq!(format!("{:x}", crate::digest_hex::LowerHex(Sha256::digest(archive.as_bytes()))), fixed_hash);
        for edit in row["edits"].as_array().unwrap().iter().rev() {
            let after = edit["after"].as_str().unwrap(); assert_eq!(source.matches(after).count(), 1);
            source = source.replacen(after, edit["before"].as_str().unwrap(), 1);
        }
        assert_eq!(source, *archive);
    }
    let start = old.find("pub(in crate::cleanup_plan::replay) fn validate_status_sources_retained").unwrap();
    let end = old.find("\n// The retained key proof").unwrap();
    assert_eq!(include_str!("status_before.rs"), format!(
        "//! Complete pre-reuse status receiver, independently compiled.\nuse super::*;\n\n{}\n", &old[start..end]));
}

