//! Status-only insertion over the exact held immutable key set. No lookup authority.
use super::*;
use crate::bounded_output::classifier_string::ClassifierLedger;
use std::cell::Cell;
use std::mem::size_of;

#[derive(Clone, Copy)]
enum Refusal {
    Binding,
    Invocation,
    Budget,
}

// Held only during the actual current source-order insertion loop. Raw pointers
// are compared, never dereferenced; moving either receiver fails closed.
pub(in crate::cleanup_plan::replay::expression_facts::receiving) struct Owner<'hir> {
    function: &'hir ResolvedFunction,
    directory: *const Directory<&'hir StatusSourceId>,
    budget: *const ReplayBudget,
    ledger: ClassifierLedger,
    next: Cell<usize>,
    first: Cell<Option<Refusal>>,
}
impl<'hir> Owner<'hir> {
    pub(in crate::cleanup_plan::replay::expression_facts::receiving) fn new(
        function: &'hir ResolvedFunction,
        directory: &Directory<&'hir StatusSourceId>,
        budget: &mut ReplayBudget,
    ) -> Result<Self, Diagnostic> {
        budget.reserve_bytes(
            function,
            2 * size_of::<Self>() + size_of::<Result<Self, Diagnostic>>(),
            directory.phase,
        )?;
        budget.charge(function, 3, directory.phase)?;
        if !directory.nodes.is_empty() || directory.root != NIL || directory.first != NIL {
            return Err(budget.budget_refusal(
                function,
                "status prefix insertion requires a fresh current directory",
                "",
            ));
        }
        // Six actual initialized binding/control fields, one unit each.
        budget.charge(function, 6, directory.phase)?;
        Ok(Self {
            function,
            directory,
            budget,
            ledger: ClassifierLedger::capture(),
            next: Cell::new(0),
            first: Cell::new(None),
        })
    }
    fn refuse(
        &self,
        reason: Refusal,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Diagnostic {
        let selected = self.first.get().unwrap_or(reason);
        self.first.set(Some(selected));
        budget.budget_refusal(
            function,
            match selected {
                Refusal::Binding => {
                    "status prefix insertion belongs to another subject or receiver"
                }
                Refusal::Invocation => "status prefix insertion belongs to another invocation",
                Refusal::Budget => "selected status prefix insertion budget already failed",
            },
            "",
        )
    }
    fn authenticate(
        &self,
        directory: &Directory<&'hir StatusSourceId>,
        function: &ResolvedFunction,
        key: &StatusSourceId,
        budget: &mut ReplayBudget,
    ) -> Result<(), Diagnostic> {
        if let Some(first) = self.first.get() {
            return Err(self.refuse(first, function, budget));
        }
        if !std::ptr::eq(self.function, function)
            || !std::ptr::eq(self.directory, directory)
            || !std::ptr::eq(self.budget, budget)
        {
            return Err(self.refuse(Refusal::Binding, function, budget));
        }
        if !self.ledger.current() {
            return Err(self.refuse(Refusal::Invocation, function, budget));
        }
        budget.reserve_bytes(function, 0, directory.phase)?;
        budget.charge(function, 0, directory.phase)?;
        // One exact indexed current-row identity test; no textual ID parsing or
        // extra full-function scan precedes the original duplicate frontier.
        budget.charge(function, 1, directory.phase)?;
        if function
            .cleanup_plan
            .status_sources
            .get(self.next.get())
            .is_none_or(|source| !std::ptr::eq(&source.id, key))
        {
            return Err(self.refuse(Refusal::Binding, function, budget));
        }
        Ok(())
    }
}

struct Search {
    probe: Probe,
    at: usize,
    maximum: usize,
    lower: usize,
    upper: usize,
    prefix: usize,
}
struct Comparison<'a> {
    left: &'a [u8],
    right: &'a [u8],
    end: usize,
    common: usize,
}
// Existing expression-fact prefix comparator's source-derived ten bookkeeping
// operations and unchanged byte-pair/end rate. No prior local/header credit.
const COMPARISON_UNITS: usize = 10;
const COMPARISON_BYTES: usize = size_of::<Comparison<'static>>()
    + size_of::<Result<(Ordering, usize), Diagnostic>>()
    + size_of::<(Ordering, usize)>()
    + size_of::<Ordering>(); // Simultaneous complete-expression ordering local.
const SEARCH_BYTES: usize = 2 * size_of::<Search>()
    + size_of::<Result<Probe, Diagnostic>>()
    + size_of::<Probe>()
    + size_of::<&StatusSourceId>(); // Simultaneously received minimum key.

fn compare(
    function: &ResolvedFunction,
    query: &StatusSourceId,
    candidate: &StatusSourceId,
    prefix: usize,
    budget: &mut ReplayBudget,
    phase: &'static str,
) -> Result<(Ordering, usize), Diagnostic> {
    budget.reserve_bytes(function, COMPARISON_BYTES, phase)?;
    budget.charge(function, COMPARISON_UNITS, phase)?;
    let mut comparison = Comparison {
        left: query.expression.as_str().as_bytes(),
        right: candidate.expression.as_str().as_bytes(),
        end: query
            .expression
            .as_str()
            .len()
            .min(candidate.expression.as_str().len()),
        common: prefix,
    };
    let units = comparison
        .end
        .checked_sub(prefix)
        .and_then(|n| n.checked_add(1))
        .ok_or_else(|| overflow(function, budget, "directory key comparison work overflow"))?;
    budget.charge(function, units, phase)?;
    while comparison.common < comparison.end {
        let a = comparison.left[comparison.common];
        let b = comparison.right[comparison.common];
        if a != b {
            return Ok((a.cmp(&b), comparison.common));
        }
        comparison.common += 1;
    }
    // New scalar ordering receipt and equal-expression branch, before either.
    budget.charge(function, 2, phase)?;
    let order = comparison.left.len().cmp(&comparison.right.len());
    if order != Ordering::Equal {
        return Ok((order, comparison.common));
    }
    budget.charge(function, 1, phase)?;
    Ok((query.lane.cmp(&candidate.lane), comparison.common))
}

impl<'hir> Directory<&'hir StatusSourceId> {
    fn certified_probe(
        &self,
        function: &ResolvedFunction,
        key: &StatusSourceId,
        budget: &mut ReplayBudget,
    ) -> Result<Probe, Diagnostic> {
        budget.reserve_bytes(function, SEARCH_BYTES, self.phase)?;
        // Six Search fields plus five nested Probe fields, one unit each.
        budget.charge(function, 11, self.phase)?;
        let mut search = Search {
            probe: Probe {
                found: false,
                parent: NIL,
                before: NIL,
                after: NIL,
                side: Ordering::Equal,
            },
            at: self.root,
            maximum: self.root,
            lower: 0,
            upper: 0,
            prefix: 0,
        };
        budget.charge(function, VISIT_UNITS, self.phase)?;
        let minimum = self.nodes[self.first].key;
        budget.charge(function, 1, self.phase)?;
        search.lower = compare(function, key, minimum, 0, budget, self.phase)?.1;
        loop {
            budget.charge(function, VISIT_UNITS, self.phase)?;
            let node = &self.nodes[search.maximum];
            if node.right == NIL {
                budget.charge(function, 1, self.phase)?;
                search.upper = compare(function, key, node.key, 0, budget, self.phase)?.1;
                break;
            }
            budget.charge(function, 1, self.phase)?;
            search.maximum = node.right;
        }
        budget.charge(function, 1, self.phase)?;
        search.prefix = search.lower.min(search.upper);
        // All stored expression keys lie between these real min/max keys.
        // Byte strings sharing a prefix form a contiguous ordered interval.
        // Lane is secondary, so every held key shares these certified bytes.
        while search.at != NIL {
            budget.charge(function, VISIT_UNITS, self.phase)?;
            let node = &self.nodes[search.at];
            budget.charge(function, 1, self.phase)?;
            search.probe.side =
                compare(function, key, node.key, search.prefix, budget, self.phase)?.0;
            if search.probe.side == Ordering::Equal {
                budget.charge(function, 1, self.phase)?;
                search.probe.found = true;
                return Ok(search.probe);
            }
            budget.charge(function, 3, self.phase)?;
            search.probe.parent = search.at;
            if search.probe.side == Ordering::Less {
                search.probe.after = search.at;
                search.at = node.left;
            } else {
                search.probe.before = search.at;
                search.at = node.right;
            }
        }
        Ok(search.probe)
    }
    pub(in crate::cleanup_plan::replay::expression_facts::receiving) fn insert_certified(
        &mut self,
        function: &ResolvedFunction,
        key: &'hir StatusSourceId,
        budget: &mut ReplayBudget,
        owner: &Owner<'hir>,
    ) -> Result<bool, Diagnostic> {
        let result = (|| {
            owner.authenticate(self, function, key, budget)?;
            // No repeated-prefix opportunity exists with fewer than two keys.
            budget.charge(function, 1, self.phase)?;
            if self.nodes.len() < 2 {
                return self.insert(function, key, budget);
            }
            self.authenticate(function, budget)?;
            let probe = self.certified_probe(function, key, budget)?;
            if probe.found {
                return Ok(false);
            }
            // Exact unchanged append/grow/link/rebalance sequence from insert.
            self.grow(function, budget)?;
            budget.charge(function, VISIT_UNITS, self.phase)?;
            let index = self.nodes.len();
            self.nodes.push(Node {
                key,
                left: NIL,
                right: NIL,
                parent: probe.parent,
                next: probe.after,
                height: 1,
            });
            if probe.before == NIL {
                self.first = index;
            } else {
                self.nodes[probe.before].next = index;
            }
            if probe.parent == NIL {
                self.root = index;
            } else if probe.side == Ordering::Less {
                self.nodes[probe.parent].left = index;
            } else {
                self.nodes[probe.parent].right = index;
            }
            self.rebalance(probe.parent, function, budget)?;
            Ok(true)
        })();
        match result {
            Ok(inserted) => {
                budget.charge(function, 1, self.phase).inspect_err(|_| {
                    owner.first.set(Some(Refusal::Budget));
                })?;
                owner.next.set(owner.next.get() + 1);
                Ok(inserted)
            }
            Err(error) => {
                if owner.first.get().is_none() {
                    owner.first.set(Some(Refusal::Budget));
                }
                Err(error)
            }
        }
    }
}

#[cfg(test)]
mod tests;

//! Full old AVL shape and complete actual receiver/last-Drop controls.
use super::*;
use crate::bounded_output::{ReservationRefusal, with_limit_usage_refusal};
use crate::test_allocation_observer::{Metrics, current_metrics, measure};

fn function(keys: &[(&str, StatusLane)]) -> ResolvedFunction {
    let mut program = crate::hir::resolve(&crate::check(
        "module prefix.status; @id(\"status.f\") fn f(x:i64)->i64{x+1} @id(\"status.main\") fn main()->i64{0}",
        "status-prefix.spx").unwrap()).unwrap();
    let index = program
        .functions
        .iter()
        .position(|f| f.id.as_str() == "status.f")
        .unwrap();
    let mut function = program.functions.swap_remove(index);
    function.cleanup_plan.status_sources = keys
        .iter()
        .map(|(key, lane)| StatusSource {
            id: StatusSourceId {
                expression: ExpressionId::from_owned((*key).to_owned()),
                lane: *lane,
            },
            producer: StatusProducer::ContractFalse {
                phase: crate::cleanup_plan::ContractPhase::Requires,
                ordinal: 0,
            },
        })
        .collect();
    function
}
fn same_tree(old: &Directory<&StatusSourceId>, current: &Directory<&StatusSourceId>) {
    assert_eq!(
        (old.root, old.first, old.len()),
        (current.root, current.first, current.len())
    );
    assert!(old.balanced() && current.balanced());
    assert!(old.keys().eq(current.keys()));
    for (a, b) in old.nodes.iter().zip(&current.nodes) {
        assert_eq!(a.key, b.key);
        assert_eq!(
            (a.left, a.right, a.parent, a.next, a.height),
            (b.left, b.right, b.parent, b.next, b.height)
        );
    }
}
#[test]
fn certified_status_insertion_keeps_complete_original_avl_shape_and_byte_lane_order() {
    let names = [
        "",
        "\0",
        "a",
        "a\0",
        "aé",
        "a界",
        "a\u{10ffff}",
        "aa",
        "ab",
        "z",
    ];
    let lanes = [
        StatusLane::OwnerAdmission,
        StatusLane::OperationFailure,
        StatusLane::AllocationFailure,
        StatusLane::ContractFalse,
    ];
    let keys: Vec<_> = names
        .iter()
        .flat_map(|name| lanes.iter().map(|lane| (*name, *lane)))
        .collect();
    for mut order in [
        keys.clone(),
        keys.iter().rev().copied().collect(),
        (0..keys.len())
            .map(|i| keys[(i * 17) % keys.len()])
            .collect(),
    ] {
        order.push(order[0]);
        order.push(*order.last().unwrap());
        let function = function(&order);
        let (((), allocation), refused, paid, first) = with_limit_usage_refusal(usize::MAX, || {
            measure(|| {
                let mut old_budget = ReplayBudget::new();
                let mut budget = ReplayBudget::new();
                let mut old = Directory::new(
                    &function,
                    &mut old_budget,
                    "cleanup status identity directory",
                )
                .unwrap();
                let mut current =
                    Directory::new(&function, &mut budget, "cleanup status identity directory")
                        .unwrap();
                let owner = Owner::new(&function, &current, &mut budget).unwrap();
                for source in &function.cleanup_plan.status_sources {
                    let expected = old.insert(&function, &source.id, &mut old_budget).unwrap();
                    let actual = current
                        .insert_certified(&function, &source.id, &mut budget, &owner)
                        .unwrap();
                    assert_eq!(actual, expected);
                    same_tree(&old, &current);
                }
                drop(owner);
                drop(old);
                drop(current);
                drop(old_budget);
                drop(budget);
            })
        });
        assert!(!refused && first.is_none());
        assert!(
            !allocation.invalid && allocation.live == 0 && allocation.allocated == allocation.freed
        );
        assert!(allocation.allocated <= paid && allocation.highwater <= paid);
    }
    let stem = "status.shared-prefix.界\0".repeat(16);
    let names: Vec<_> = (0..129).map(|i| format!("{stem}{i:03}")).collect();
    let keys: Vec<_> = names
        .iter()
        .map(|name| (name.as_str(), StatusLane::OperationFailure))
        .collect();
    let function = function(&keys);
    let (((), allocation), refused, paid, first) = with_limit_usage_refusal(usize::MAX, || {
        measure(|| {
            let mut old_budget = ReplayBudget::new();
            let mut budget = ReplayBudget::new();
            let mut old = Directory::new(
                &function,
                &mut old_budget,
                "cleanup status identity directory",
            )
            .unwrap();
            let mut current =
                Directory::new(&function, &mut budget, "cleanup status identity directory")
                    .unwrap();
            let owner = Owner::new(&function, &current, &mut budget).unwrap();
            for source in &function.cleanup_plan.status_sources {
                assert_eq!(
                    old.insert(&function, &source.id, &mut old_budget).unwrap(),
                    current
                        .insert_certified(&function, &source.id, &mut budget, &owner)
                        .unwrap()
                );
                same_tree(&old, &current);
            }
            assert!(
                budget.remaining > old_budget.remaining,
                "only this actual repeated-prefix construction has a source-specific work reduction"
            );
            drop(owner);
            drop(old);
            drop(current);
            drop(old_budget);
            drop(budget);
        })
    });
    assert!(!refused && first.is_none());
    assert!(
        !allocation.invalid && allocation.live == 0 && allocation.allocated == allocation.freed
    );
    assert!(allocation.allocated <= paid && allocation.highwater <= paid);
}

fn observe(
    function: &ResolvedFunction,
    current: bool,
    work: usize,
    bytes: usize,
) -> (
    (bool, usize, Metrics),
    bool,
    usize,
    Option<ReservationRefusal>,
) {
    let expected_work = Diagnostic::io(
        "SPX-H006",
        format!(
            "cleanup plan for function `{}` failed independent replay: cleanup replay work budget exhausted during cleanup status identity directory",
            function.id
        ),
    );
    let ((value, allocation), refused, paid, first) = with_limit_usage_refusal(bytes, || {
        measure(|| {
            let mut budget = ReplayBudget::new();
            budget.remaining = work;
            let mut directory =
                match Directory::new(function, &mut budget, "cleanup status identity directory") {
                    Ok(value) => value,
                    Err(error) => {
                        drop(error);
                        drop(budget);
                        return (false, 0);
                    }
                };
            let owner = if current {
                match Owner::new(function, &directory, &mut budget) {
                    Ok(value) => Some(value),
                    Err(error) => {
                        if bytes == usize::MAX {
                            assert_eq!(error, expected_work);
                        }
                        drop(error);
                        let at = current_metrics().allocated;
                        let retry = Owner::new(function, &directory, &mut budget)
                            .err()
                            .expect("selected setup refusal remains sticky");
                        assert_eq!(retry, Diagnostic::io("SPX-H006", String::new()));
                        drop(retry);
                        assert_eq!(current_metrics().allocated, at);
                        drop(directory);
                        let used = work - budget.remaining;
                        drop(budget);
                        return (false, used);
                    }
                }
            } else {
                None
            };
            let mut success = true;
            for source in &function.cleanup_plan.status_sources {
                let result = match &owner {
                    Some(owner) => {
                        directory.insert_certified(function, &source.id, &mut budget, owner)
                    }
                    None => directory.insert(function, &source.id, &mut budget),
                };
                match result {
                    Ok(inserted) => assert!(inserted),
                    Err(error) => {
                        assert_eq!(error.code, "SPX-H006");
                        assert_eq!(error.severity, crate::diagnostic::Severity::Error);
                        assert_eq!(error.path, None);
                        assert_eq!(error.span, None);
                        assert_eq!(error.help, None);
                        if bytes == usize::MAX {
                            assert_eq!(error, expected_work);
                        }
                        drop(error);
                        success = false;
                        let at = current_metrics().allocated;
                        let remaining = budget.remaining;
                        let retry = match &owner {
                            Some(owner) => {
                                directory.insert_certified(function, &source.id, &mut budget, owner)
                            }
                            None => directory.insert(function, &source.id, &mut budget),
                        };
                        assert_eq!(retry, Err(Diagnostic::io("SPX-H006", String::new())));
                        drop(retry);
                        assert_eq!(current_metrics().allocated, at);
                        assert_eq!(budget.remaining, remaining);
                        break;
                    }
                }
            }
            let used = work - budget.remaining;
            drop(owner);
            drop(directory);
            drop(budget);
            (success, used)
        })
    });
    assert!(
        !allocation.invalid && allocation.live == 0 && allocation.allocated == allocation.freed
    );
    assert!(allocation.allocated <= paid && allocation.highwater <= paid);
    ((value.0, value.1, allocation), refused, paid, first)
}
#[test]
fn certified_status_actual_work_and_every_small_byte_frontier_are_sticky_through_drop() {
    let function = function(&[
        ("same.0", StatusLane::OperationFailure),
        ("same.1", StatusLane::OperationFailure),
        ("same.2", StatusLane::OperationFailure),
    ]);
    for current in [false, true] {
        let ((ok, work, _), refused, bytes, first) =
            observe(&function, current, MAX_REPLAY_WORK_UNITS, usize::MAX);
        assert!(ok && !refused && first.is_none());
        for limit in 0..=work {
            let ((ok, used, _), refused, _, _) = observe(&function, current, limit, usize::MAX);
            assert_eq!(ok, limit == work);
            assert!(!refused);
            assert_eq!(used, limit);
        }
        for limit in 0..=bytes {
            let ((ok, _, allocation), refused, used, first) =
                observe(&function, current, MAX_REPLAY_WORK_UNITS, limit);
            assert_eq!(ok, limit == bytes);
            assert_eq!(refused, !ok);
            assert_eq!(first.is_some(), !ok);
            assert!(used <= limit);
            if limit == 0 {
                assert_eq!(allocation.allocated, 0);
            }
        }
    }
}
#[test]
fn certified_status_foreign_restored_and_wrong_subject_never_reactivate_the_bound_owner() {
    let function = function(&[
        ("same.0", StatusLane::OperationFailure),
        ("same.1", StatusLane::ContractFalse),
    ]);
    let expected = Diagnostic::io(
        "SPX-H006",
        format!(
            "cleanup plan for function `{}` failed independent replay: status prefix insertion belongs to another invocation",
            function.id
        ),
    );
    for cached in [false, true] {
        let (((), allocation), refused, _, first) = with_limit_usage_refusal(usize::MAX, || {
            measure(|| {
                let mut budget = ReplayBudget::new();
                let mut directory =
                    Directory::new(&function, &mut budget, "cleanup status identity directory")
                        .unwrap();
                let owner = Owner::new(&function, &directory, &mut budget).unwrap();
                if cached {
                    assert!(
                        directory
                            .insert_certified(
                                &function,
                                &function.cleanup_plan.status_sources[0].id,
                                &mut budget,
                                &owner
                            )
                            .unwrap()
                    );
                }
                let len = directory.len();
                let pointer = directory.nodes.as_ptr();
                let key = &function.cleanup_plan.status_sources[usize::from(cached)].id;
                let (_, child_refused, child_paid, _) =
                    with_limit_usage_refusal(usize::MAX, || {
                        let at = current_metrics().allocated;
                        let error = directory
                            .insert_certified(&function, key, &mut budget, &owner)
                            .unwrap_err();
                        assert_eq!(error, expected);
                        drop(error);
                        assert_eq!(current_metrics().allocated, at);
                    });
                assert!(!child_refused && child_paid == 0);
                assert!(matches!(owner.first.get(), Some(Refusal::Invocation)));
                // The nested test ledger setup/Drop remains wholly observed.
                let at = current_metrics().allocated;
                let error = directory
                    .insert_certified(&function, key, &mut budget, &owner)
                    .unwrap_err();
                assert_eq!(error, Diagnostic::io("SPX-H006", String::new()));
                drop(error);
                assert_eq!(current_metrics().allocated, at);
                assert_eq!(directory.len(), len);
                assert_eq!(directory.nodes.as_ptr(), pointer);
                drop(owner);
                drop(directory);
                drop(budget);
            })
        });
        assert!(refused && first.is_some());
        assert!(
            !allocation.invalid && allocation.live == 0 && allocation.allocated == allocation.freed
        );
    }
    let wrong = function.clone();
    let expected = Diagnostic::io(
        "SPX-H006",
        format!(
            "cleanup plan for function `{}` failed independent replay: status prefix insertion belongs to another subject or receiver",
            wrong.id
        ),
    );
    let (((), allocation), _, paid, _) = with_limit_usage_refusal(usize::MAX, || {
        measure(|| {
            let mut budget = ReplayBudget::new();
            let mut directory =
                Directory::new(&function, &mut budget, "cleanup status identity directory")
                    .unwrap();
            let owner = Owner::new(&function, &directory, &mut budget).unwrap();
            let result = directory.insert_certified(
                &wrong,
                &wrong.cleanup_plan.status_sources[0].id,
                &mut budget,
                &owner,
            );
            assert_eq!(result.unwrap_err(), expected);
            assert!(matches!(owner.first.get(), Some(Refusal::Binding)));
            drop(owner);
            drop(directory);
            drop(budget);
        })
    });
    assert!(
        !allocation.invalid && allocation.live == 0 && allocation.allocated == allocation.freed
    );
    assert!(allocation.allocated <= paid && allocation.highwater <= paid);
}

//! Complete status-fact reuse receiver before prefix insertion, independently compiled.
use super::*;

pub(in crate::cleanup_plan::replay) fn validate_status_sources_retained<'hir>(
    function: &'hir ResolvedFunction,
    facts: &Facts<'_>,
    budget: &mut ReplayBudget,
) -> Result<StatusSources<'hir>, Diagnostic> {
    if let Facts::Tree(tree) = facts {
        super::super::super::validate_status_sources(function, tree)?;
        budget.reserve_bytes(function, CONTROL_BYTES, "retained status full controls")?;
        return Ok(StatusSources { function, budget, ledger: ClassifierLedger::capture(), ids: None });
    }
    let expressions: &dyn Lookup = facts;
    let mut ids = Directory::new(function, budget, "cleanup status identity directory")?;
    for source in &function.cleanup_plan.status_sources {
        if !ids.insert(function, &source.id, budget)? {
            return Err(<Diagnostic as semantic_refusal::Error>::structural(
                function,
                semantic_refusal::Atom::RepeatedStatus(source.id.expression.clone()),
            ));
        }
        // Retain the actual first lookup's borrowed payload, only through this
        // immutable source's producer match. Pay its complete receiving pointer
        // and one assignment step; no previous result/header credit is used.
        budget.reserve_bytes(function,
            std::mem::size_of::<&Option<CallFact<'_>>>(),
            "retained status fact receiving control")?;
        budget.charge(function, 1, "retained status fact receiving assignment")?;
        let Some(fact) = expressions.fact(function, &source.id.expression, budget)? else {
            return Err(<Diagnostic as semantic_refusal::Error>::structural(
                function,
                semantic_refusal::Atom::UnknownStatus(source.id.expression.clone()),
            ));
        };
        match (&source.id.lane, &source.producer) {
            (
                StatusLane::OperationFailure | StatusLane::OwnerAdmission,
                StatusProducer::PropagatedCall { callee },
            ) => {
                // The payload reference is a second simultaneous receiving
                // control; the eliminated lookup's result is not a credit.
                budget.reserve_bytes(function, std::mem::size_of::<&CallFact<'_>>(),
                    "retained status call receiving control")?;
                budget.charge(function, 1, "retained status call receiving assignment")?;
                let Some(call) = fact
                else {
                    return Err(replay_error(
                        function,
                        "propagated-call status source does not name a call expression",
                    ));
                };
                if call.callee.as_ref() != callee {
                    return Err(replay_error(
                        function,
                        "propagated-call status source names the wrong callee",
                    ));
                }
            }
            (
                StatusLane::OperationFailure,
                StatusProducer::CheckedArithmetic {
                    normalized_cases, ..
                },
            ) => {
                let mut cases = Directory::new(
                    function,
                    budget,
                    "cleanup checked arithmetic case directory",
                )?;
                for case in normalized_cases {
                    cases.insert(function, *case, budget)?;
                }
                if cases.is_empty() || cases.len() != normalized_cases.len() {
                    return Err(replay_error(
                        function,
                        "checked-arithmetic status cases are empty or repeated",
                    ));
                }
            }
            (
                StatusLane::AllocationFailure,
                StatusProducer::CheckedAllocation {
                    normalized_cases, ..
                },
            ) if function.cleanup_plan.schema == crate::cleanup_plan::CLEANUP_PLAN_SCHEMA_V20
                && *normalized_cases
                    == [
                        crate::cleanup_plan::AllocationCase::PayloadRefused,
                        crate::cleanup_plan::AllocationCase::SizeOverflow,
                    ] => {}
            (StatusLane::ContractFalse, StatusProducer::ContractFalse { .. }) => {}
            _ => {
                return Err(replay_error(
                    function,
                    "status source lane does not match its producer",
                ));
            }
        }
    }
    budget.reserve_bytes(function, CONTROL_BYTES, "retained status full controls")?;
    Ok(StatusSources { function, budget, ledger: ClassifierLedger::capture(), ids: Some(ids) })
}

//! Complete measured status-fact component before the additive prefix route.
use super::*;
use crate::bounded_output::{with_limit_usage_refusal, ReservationRefusal};
use crate::test_allocation_observer::measure;

#[allow(clippy::too_many_arguments)]
fn receive(program: &ResolvedProgram, function: &ResolvedFunction, facts: &Facts<'_>,
    storage: &BTreeSet<StorageId>, leaves: &Leaves, budget: &mut ReplayBudget,
    current: bool) -> Result<(), Diagnostic>
{
    let statuses = if current {
        status_before_prefix::validate_status_sources_retained(function, facts, budget)?
    } else {
        status_before::validate_status_sources_retained(function, facts, budget)?
    };
    validate_blocks_and_edges_retained(program, function, facts, storage, leaves,
        None, budget, &statuses)
}

// HIR/facts are existing immutable inputs. Every receiver allocation, result,
// retained token and budget drops while the actual observer is still active.
pub(super) fn observe(program: &ResolvedProgram, function: &ResolvedFunction, current: bool,
    work_limit: usize, byte_limit: usize, expected: Option<&Result<(), Diagnostic>>)
    -> (bool, usize, usize, bool, Option<ReservationRefusal>, usize)
{
    let mut preparation = ReplayBudget::unobserved();
    let facts = Facts::Arena(super::super::super::arena::build::<errors::Legacy>(function,
        capacity::Payer::Selected(&mut physical_storage::PhysicalReservation::new(usize::MAX)),
        &mut preparation).unwrap());
    let storage = validate_slots(function).unwrap();
    let leaves = collect_leaves(function).unwrap();
    let ((value, allocation), refused, debit, first) = with_limit_usage_refusal(byte_limit, || measure(|| {
        let mut budget = ReplayBudget::new();
        budget.remaining = work_limit;
        let result = receive(program, function, &facts, &storage, &leaves, &mut budget, current);
        if let Some(expected) = expected { assert_eq!(&result, expected); }
        let success = result.is_ok();
        if !success && work_limit < MAX_REPLAY_WORK_UNITS && byte_limit == 1 << 26 {
            assert_eq!(result.as_ref().unwrap_err().code, "SPX-H006");
            assert_eq!(budget.remaining, 0);
        }
        let used = work_limit - budget.remaining;
        drop(result);
        if !success && (work_limit < MAX_REPLAY_WORK_UNITS || byte_limit < 1 << 26) {
            let remaining = budget.remaining;
            let bytes = crate::bounded_output::active_remaining();
            let retry = receive(program, function, &facts, &storage, &leaves, &mut budget, current);
            assert!(retry.is_err());
            assert_eq!(budget.remaining, remaining);
            assert_eq!(crate::bounded_output::active_remaining(), bytes);
            drop(retry);
        }
        drop(budget);
        (success, used)
    }));
    assert!(!allocation.invalid);
    assert_eq!(allocation.live, 0);
    assert_eq!(allocation.allocated, allocation.freed);
    (value.0, value.1, debit, refused, first, allocation.allocated)
}
